package com.siam.deviceinfo.database;import androidx.room.*;@Entity(tableName="device_records") public class UsageRecord {@PrimaryKey(autoGenerate=true) public int id;@ColumnInfo(name="kind") public String kind;@ColumnInfo(name="value") public String value;@ColumnInfo(name="created_at") public long createdAt;public UsageRecord(String kind,String value,long createdAt){this.kind=kind;this.value=value;this.createdAt=createdAt;}}
